console.log('All iPhone products:', JSON.stringify(iphones, null, 2));

// Check if any other tables might store compatibility info
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
const compatTables = tables.filter(t => t.name.toLowerCase().includes('compat'));
console.log('Compatibility tables:', JSON.stringify(compatTables));

// Also search for 'Qi' or 'wireless charging' or 'magnetic' in products
const qiProducts = db.prepare(\"SELECT product_id, name, description FROM products WHERE description LIKE '%Qi%' OR description LIKE '%wireless charg%'\").all();
console.log('Qi/wireless charging products:', JSON.stringify(qiProducts, null, 2));
"

