node -e "
const XLSX = require('xlsx');
const wb = XLSX.readFile('/workspace/testbed/data/product_inventory.xlsx');
const ws = wb.Sheets['Products'];
const data = XLSX.utils.sheet_to_json(ws, { header: 1 });

// Add the new product row
data.push([
  'PROD-2028EE',
  'Magnetic Wireless Charging Stand',
  'electronics',
  45,
  'Yes'
]);

// Rebuild sheet from data
const newWs = XLSX.utils.aoa_to_sheet(data);

// Set column widths for readability
newWs['!cols'] = [
  { wch: 14 },  // Product ID
  { wch: 40 },  // Name
  { wch: 14 },  // Category
  { wch: 8 },   // Price
  { wch: 10 },  // In Stock
];

wb.Sheets['Products'] = newWs;

// Add a 'Notes' sheet for variant & compatibility details
const notes = [
  ['Product ID', 'Field', 'Detail'],
  ['PROD-2028EE', 'Brand', 'VoltForge'],
  ['PROD-2028EE', 'Subcategory', 'Mobile Accessories'],
  ['PROD-2028EE', 'Price', 45],
  ['PROD-2028EE', 'Stock Quantity', 96],
  ['PROD-2028EE', 'Shipping Days', 3],
  ['PROD-2028EE', 'Warranty (months)', 12],
  ['PROD-2028EE', 'Return Window (days)', 30],
  ['PROD-2028EE', 'Restocking Fee (%)', 0],
  ['PROD-2028EE', 'Gift Wrap Available', 'Yes'],
  ['PROD-2028EE', 'Backorder Available', 'No'],
  ['PROD-2028EE', 'Rating', 3.9],
  ['PROD-2028EE', 'Review Count', 459],
  ['PROD-2028EE', 'Variants', 'None — single SKU, no color/size/config options'],
  ['PROD-2028EE', 'Compatibility Note', 'No explicit compatibility records in database. Description indicates support for Qi-enabled phones (up to 15W). iPhone 15 supports Qi wireless charging, so it is expected to be compatible, but this is inferred — not manufacturer-confirmed.'],
  ['PROD-2028EE', 'Description', 'New magnetic wireless charging stand in black for Qi-enabled phones with up to 15W charging. Physical goods accessory with taxable retail pricing and inventory tracking enabled.'],
];

const notesWs = XLSX.utils.aoa_to_sheet(notes);
notesWs['!cols'] = [
  { wch: 14 },
  { wch: 22 },
  { wch: 90 },
];
XLSX.utils.book_append_sheet(wb, notesWs, 'PROD-2028EE Details');

XLSX.writeFile(wb, '/workspace/testbed/data/product_inventory.xlsx');
console.log('File updated successfully.');
"

